const STARTER_PHONETICS = {
  bug:["/bʌɡ/","巴哥"],hug:["/hʌɡ/","哈哥"],mug:["/mʌɡ/","馬哥"],rug:["/rʌɡ/","拉哥"],jug:["/dʒʌɡ/","加哥"],
  cake:["/keɪk/","ㄎ欸克"],lake:["/leɪk/","ㄌ欸克"],make:["/meɪk/","ㄇ欸克"],take:["/teɪk/","ㄊ欸克"],wake:["/weɪk/","ㄨ欸克"],
  ball:["/bɔːl/","包奧"],call:["/kɔːl/","靠奧"],fall:["/fɔːl/","佛奧"],tall:["/tɔːl/","套奧"],wall:["/wɔːl/","沃奧"]
};
window.CORE_WORDS = VOCABULARY_SOURCE.trim().split("\n").map((line,index)=>{
  const [word,zh,topic]=line.split("|");
  const phonetic=STARTER_PHONETICS[word]||["","按喇叭聽美式發音"];
  return {id:index+1,word,zh,topic,ipa:phonetic[0],hint:phonetic[1]};
});

const normalized=new Set(window.CORE_WORDS.map(item=>item.word.toLowerCase()));
if(window.CORE_WORDS.length!==365) throw new Error(`核心詞庫應為 365 字，目前為 ${window.CORE_WORDS.length} 字`);
if(normalized.size!==365) throw new Error("核心詞庫含有重複英文單字");

